import { NextFunction, Request, Response } from "express";
import { ConflictError, DomainError, NotFoundError, ValidationError } from "../domain/errors";

function statusFor(error: unknown): number {
  if (error instanceof NotFoundError) return 404;
  if (error instanceof ConflictError) return 409;
  if (error instanceof ValidationError) return 400;
  if (error instanceof DomainError) return 422;
  return 500;
}

export function errorHandlerMiddleware(
  error: unknown,
  _req: Request,
  res: Response,
  _next: NextFunction,
): void {
  const status = statusFor(error);
  const message = status === 500 || !(error instanceof Error) ? "internal server error" : error.message;
  res.status(status).json({ error: message });
}

