import { Task } from "../domain/task";
import { TaskFilter, TaskRepository } from "../domain/task-repository";

export class InMemoryTaskRepository implements TaskRepository {
  private readonly items = new Map<string, Task>();

  async save(task: Task): Promise<void> {
    this.items.set(task.id, task);
  }

  async findById(id: string): Promise<Task | undefined> {
    return this.items.get(id);
  }

  async findByProject(projectId: string, filter: TaskFilter): Promise<Task[]> {
    return [...this.items.values()].filter(
      (task) =>
        task.projectId === projectId &&
        (filter.status === undefined || task.status === filter.status) &&
        (filter.assigneeId === undefined || task.assigneeId === filter.assigneeId),
    );
  }
}

